143	type apiKeyTransport struct {
144		// Key is the API Key to set on requests.
145		Key string
146		// Transport is the underlying HTTP transport.
147		// If nil, http.DefaultTransport is used.
148		Transport http.RoundTripper
149	}
150	
151	func (t *apiKeyTransport) RoundTrip(req *http.Request) (*http.Response, error) {
152		newReq := *req
153		args := newReq.URL.Query()
154		args.Set("key", t.Key)
155		newReq.URL.RawQuery = args.Encode()
156		return t.Transport.RoundTrip(&newReq)
157	}
