179	func addOpenTelemetryTransport(trans http.RoundTripper, opts *Options) http.RoundTripper {
180		if opts.DisableTelemetry {
181			return trans
182		}
183		if gax.IsFeatureEnabled("METRICS") || gax.IsFeatureEnabled("TRACING") {
184			trans = &otelAttributeTransport{base: trans}
185		}
186		if !gax.IsFeatureEnabled("TRACING") {
187			return otelhttp.NewTransport(trans)
188		}
189		var staticAttrs []attribute.KeyValue
190		if opts.InternalOptions != nil {
191			staticAttrs = transport.StaticTelemetryAttributes(opts.InternalOptions.TelemetryAttributes)
192		}
193		otelOpts := []otelhttp.Option{
194			otelhttp.WithSpanOptions(trace.WithAttributes(staticAttrs...)),
195		}
196		return otelhttp.NewTransport(trans, otelOpts...)
197	}
