608	func (h *otelHandler) handleRPCError(ctx context.Context, span trace.Span, logger *slog.Logger, end *stats.End) {
609		info := gax.ExtractTelemetryErrorInfo(ctx, end.Error)
610	
611		if logger != nil {
612			logActionableError(ctx, logger, info)
613		}
614	
615		if span != nil {
616			attrs := []attribute.KeyValue{
617				attribute.String("error.type", info.ErrorType),
618				attribute.String("status.message", info.StatusMessage),
619				attribute.String("rpc.response.status_code", info.StatusCode),
620				attribute.String("exception.type", fmt.Sprintf("%T", end.Error)),
621			}
622			span.SetAttributes(attrs...)
623		}
624	}
625	
626	func (h *otelHandler) handleRPCSuccess(span trace.Span) {
627		if span != nil {
628			attrs := []attribute.KeyValue{
629				attribute.String("rpc.response.status_code", "OK"),
630			}
631			span.SetAttributes(attrs...)
632		}
633	}
