// maxErrorBodyBytes is the maximum number of bytes of an error response body
// that will be buffered in order to extract structured error details for
// logging. Bodies larger than this are not inspected; the HTTP status string is
// logged instead.
const maxErrorBodyBytes = 8192

func addOpenTelemetryTransport(trans http.RoundTripper, opts *Options) http.RoundTripper {
	if opts.DisableTelemetry {
		return trans
	}

	var staticAttrs []attribute.KeyValue
	if opts.InternalOptions != nil {
		staticAttrs = transport.StaticTelemetryAttributes(opts.InternalOptions.TelemetryAttributes)
	}

	// When logging is enabled and a logger was provided, scope it with the
	// static telemetry attributes so every emitted record carries the client
	// identity (e.g. gcp.client.version).
	var scopedLogger *slog.Logger
	if gax.IsFeatureEnabled("LOGGING") && opts.Logger != nil {
		var staticLogAttrs []any
		for _, attr := range staticAttrs {
			staticLogAttrs = append(staticLogAttrs, slog.String(string(attr.Key), attr.Value.AsString()))
		}
		scopedLogger = opts.Logger.With(staticLogAttrs...)
	}

	if gax.IsFeatureEnabled("METRICS") || gax.IsFeatureEnabled("TRACING") || gax.IsFeatureEnabled("LOGGING") {
		trans = &otelAttributeTransport{base: trans, logger: scopedLogger}
	}
	if !gax.IsFeatureEnabled("TRACING") {
		return otelhttp.NewTransport(trans)
	}
	otelOpts := []otelhttp.Option{
		otelhttp.WithSpanOptions(trace.WithAttributes(staticAttrs...)),
	}
	return otelhttp.NewTransport(trans, otelOpts...)
}

// otelAttributeTransport is a wrapper around an http.RoundTripper that adds
// custom Google Cloud-specific attributes to OpenTelemetry spans and emits
// structured debug logs for error responses.
type otelAttributeTransport struct {
	base http.RoundTripper
	// logger, when non-nil and the LOGGING feature is enabled, is used to emit
	// debug-level log records when actionable errors occur during a round trip.
	logger *slog.Logger
}

// RoundTrip intercepts the HTTP request and response to enrich the active
// OpenTelemetry span with static and dynamic attributes, as well as detailed
// error information. When logging is enabled it also emits a structured debug
// log record describing error responses.
func (t *otelAttributeTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	var span trace.Span
	if gax.IsFeatureEnabled("TRACING") {
		span = trace.SpanFromContext(req.Context())
		if span.IsRecording() {
			var attrs []attribute.KeyValue
			attrs = append(attrs, attribute.String("rpc.system.name", "http"))
			if resName, ok := callctx.TelemetryFromContext(req.Context(), "resource_name"); ok {
				attrs = append(attrs, attribute.String("gcp.resource.destination.id", resName))
			}
			if resendCountStr, ok := callctx.TelemetryFromContext(req.Context(), "resend_count"); ok {
				if count, err := strconv.Atoi(resendCountStr); err == nil {
					attrs = append(attrs, attribute.Int("http.request.resend_count", count))
				}
			}
			if urlTemplate, ok := callctx.TelemetryFromContext(req.Context(), "url_template"); ok {
				attrs = append(attrs, attribute.String("url.template", urlTemplate))
				span.SetName(fmt.Sprintf("%s %s", req.Method, urlTemplate))
			}
			span.SetAttributes(attrs...)
		}
	}

	var data *gax.TransportTelemetryData
	if gax.IsFeatureEnabled("METRICS") {
		data = gax.ExtractTransportTelemetry(req.Context())
		if data != nil && req.URL != nil {
			host := req.URL.Hostname()
			if host != "" {
				data.SetServerAddress(host)
			}
			portStr := req.URL.Port()
			if portStr == "" {
				if req.URL.Scheme == "https" {
					portStr = "443"
				} else if req.URL.Scheme == "http" {
					portStr = "80"
				}
			}
			if port, pErr := strconv.Atoi(portStr); pErr == nil {
				data.SetServerPort(port)
			}
		}
	}

	resp, err := t.base.RoundTrip(req)

	if gax.IsFeatureEnabled("TRACING") && span != nil && span.IsRecording() {
		if err != nil {
			var errorType string
			switch {
			case errors.Is(err, context.DeadlineExceeded):
				errorType = "CLIENT_TIMEOUT"
			case errors.Is(err, context.Canceled):
				errorType = "CLIENT_CANCELLED"
			default:
				errorType = "CLIENT_CONNECTION_ERROR"
			}
			span.SetAttributes(
				attribute.String("error.type", errorType),
				attribute.String("status.message", err.Error()),
				attribute.String("exception.type", fmt.Sprintf("%T", err)),
			)
		} else {
			span.SetAttributes(attribute.Int("http.response.status_code", resp.StatusCode))
			if resp.StatusCode >= 400 {
				errorType := strconv.Itoa(resp.StatusCode)
				span.SetAttributes(
					attribute.String("error.type", errorType),
					attribute.String("status.message", resp.Status),
				)
			}
		}
	}

	// Structured logging of error responses is independent of tracing and
	// metrics.
	var logger *slog.Logger
	if gax.IsFeatureEnabled("LOGGING") {
		if l := t.logger; l != nil && l.Enabled(req.Context(), slog.LevelDebug) {
			logger = l
		}
	}
	if logger == nil {
		return resp, err
	}

	if err != nil {
		// No HTTP response was received; log immediately using the transport
		// error to classify the failure.
		info := gax.ExtractTelemetryErrorInfo(req.Context(), err)
		msg := info.StatusMessage
		if msg == "" {
			msg = err.Error()
		}
		logError(req.Context(), logger, req, nil, info, msg)
		return resp, err
	}

	if resp == nil || resp.StatusCode < 400 {
		return resp, err
	}

	// The response is an error. If the advertised body is too large to buffer,
	// log immediately using the HTTP status string and leave the body untouched.
	if resp.ContentLength > maxErrorBodyBytes {
		info := httpStatusErrorInfo(resp.StatusCode)
		logError(req.Context(), logger, req, resp, info, resp.Status)
		return resp, err
	}

	// Otherwise, wrap the body so the log record is emitted once the body is
	// closed (or its content read past the buffering limit). This keeps any
	// active OpenTelemetry span recording at the time the record is emitted.
	resp.Body = &errorTrackingBody{
		body:   resp.Body,
		req:    req,
		resp:   resp,
		logger: logger,
	}
	return resp, err
}

